const fs = require('fs-extra');
const path = require('path');

const outputFileName = "LuaTangSengFacadeDefines.lua"

function buildContent(config) {
    var content = `export type TangSengFacade = typeof(require(game.ReplicatedStorage._robloxManifest.TangSengFacade))`
    return content
}

function gen(config, outputPath) {
    fs.ensureDirSync(outputPath);
    var content = buildContent(config)
    fs.writeFileSync(path.join(outputPath, outputFileName), content);
    console.log(`write file ${path.join(outputPath, outputFileName)}`)
}


module.exports = gen;